s=read(root/'results/paired-summary.json')['contexts'][0];raw=read(root/'results/paired-raw.json');old=read(root/'baseline-attention-summary.json')['contexts'][0];audit=read(root/'independent-audit.json');old_audit=read(root/'baseline-attention-audit.json');profile=read(root/'profile32k-analysis.json');old_profile=read(root/'baseline-attention-profile.json');freeze=read(root/'inputs/freeze.json')
latency=statistics.median(p['candidate']['prefill_ms']/p['oracle']['prefill_ms'] for p in raw['pairs']);old_latency=1/old['candidate_over_oracle']['prefill_tps']['median']
