lines+=['','| Pair | Order | Rust prefill s | Reference prefill s | Rust/reference |','|---|---|---:|---:|---:|']
for pair in raw['pairs']:
 lines.append(f"| {pair['repetition']} | {pair['order']} | {pair['candidate']['prefill_ms']/1000:.3f} | {pair['oracle']['prefill_ms']/1000:.3f} | {pair['candidate']['prefill_ms']/pair['oracle']['prefill_ms']:.5f} |")
observations=[json.loads(line) for line in (root/'load-observations.jsonl').read_text().splitlines()]
video=[obs['at_utc'] for obs in observations if any(p['process'] in ('OBS','UVCAssistant','VTDecoderXPCService') for p in obs['cpu_processes'])]
if video:lines+=['',f"OBS/camera/video activity appears in the process observations from {min(video)} through {max(video)} (the observer also covers the separate profile). Background load varies across the observations. All pairs are retained; the exact latency improvement cannot be attributed solely to the code change under these varying background conditions."]
host_before=read(root/'inputs/host-before.json');host_after=read(root/'inputs/host-after-pairs.json')
lines+=['', f"Host swap before the campaign: `{host_before['memory']['swap']}`; after the timed block: `{host_after['swap']}`. Peak process memory is an observed residency measure under these host conditions, not proof of a lower allocation requirement."]
lines+=['',f"Paired Rust/reference prefill latency ratio: {latency:.5f}. Steady decode ratio: {s['candidate_over_oracle']['gen_steady_tps']['median']:.5f}. Complete median/MAD/range distributions and independent recomputation are included.",'','## Change from the attention-batching baseline','']
for role in ['candidate','oracle']:
 before=old[role]['prefill_ms']['median']/1000;after=s[role]['prefill_ms']['median']/1000;lines.append(f"- {role.capitalize()} median prefill: {before:.3f} → {after:.3f} s ({(after/before-1)*100:+.2f}% latency).")
lines += [f"- Rust steady decode: {old['candidate']['gen_steady_tps']['median']:.3f} → {s['candidate']['gen_steady_tps']['median']:.3f} tokens/s; paired Rust/reference ratio {old['candidate_over_oracle']['gen_steady_tps']['median']:.5f} → {s['candidate_over_oracle']['gen_steady_tps']['median']:.5f}.",f"- Reference-normalized prefill improvement across campaigns: {old_latency/latency:.3f}× (paired latency ratio {old_latency:.5f} → {latency:.5f}).",f"- Rust peak memory: {old_audit['memory_distributions']['candidate']['median']:.3f} → {audit['memory_distributions']['candidate']['median']:.3f} GiB.",'','Both campaigns use the same pinned oracle-v5, model, prompt, full-output targets and greedy transcript. They are separate host sessions; the normalized comparison is descriptive. Background applications remained active, and full load/thermal observations are included.',f"The audit records {len(audit['unusual_thermal_observations'])} unusual thermal observations.",'','## Validation','', '- Initial candidate 05447277 stopped on a stale schedule-count assertion at layer 3 before HC comparison. The original failed attempt is retained; the corrected candidate completed all gates. No tensor target was changed.', '- 310 Rust tests pass. The unchanged Python toolkit retains its 93-test acceptance evidence.', '- Fresh complete 32K output-only and diagnostic runs match every prefill logit and all 128 full decode outputs to oracle-v5. Every accepted internal HC target through 24K matches.', '- The 12K native control, detailed 8K legacy control, 2K control and two retained reset/reuse cycles pass. No fixture was updated or tolerance introduced.', '- The full v5 tensors, reference repeatability and tokenizer evidence are reused unchanged from the audited baseline report. Historical failed oracle/diagnostic attempts remain preserved and explicitly separate from this candidate.', '- Existing decoder, prefix, SSD and distributed implementations are unchanged. The 32-row standalone ingress controls remain available; the native chunk uses one complete ingress batch.', '', '## Isolated profile','', 'Host elapsed time includes command waits and is not additive with GPU time.','', '| Stage group | GPU seconds | Host elapsed seconds | Calls |','|---|---:|---:|---:|']
for name,g in sorted(profile['group_totals'].items(),key=lambda item:item[1]['gpu_ms'],reverse=True):lines.append(f"| {name} | {g['gpu_ms']/1000:.3f} | {g['host_elapsed_ms']/1000:.3f} | {g['calls']} |")
a=old_profile['group_totals']['odd/ingress'];b=profile['group_totals']['odd/ingress'];leading=max(profile['group_totals'],key=lambda n:profile['group_totals'][n]['gpu_ms'])
